import{_t as e,it as t,n,rt as r}from"./chunks/framework.C6TizvAB.js";import{Ln as i,Rn as a}from"./chunks/assets.DAjhvrpn.js";var o=JSON.parse(`{"title":"Lick detection","description":"","frontmatter":{"title":"Lick detection","lang":"en-US"},"headers":[],"relativePath":"building/lick-detection.md","filePath":"building/lick-detection.md"}`),s={name:`building/lick-detection.md`};function c(n,o,s,c,l,u){return e(),r(`div`,null,[...o[0]||=[t(`<h1 id="lick-detection" tabindex="-1">Lick detection <a class="header-anchor" href="#lick-detection" aria-label="Permalink to “Lick detection”">​</a></h1><p>The lick detection module is based on a simple transistor design (Slotnick 2009), which we modified to detect licks on 2 spouts in the same module. We also added a DC-DC converter to isolate the circuit from the power source, and a 5 V voltage regulator after the relays to get a TTL signal at the output of both circuits.</p><p>The module was designed this way for a specific task that requires two spouts, but it can also be used with one spout (e.g. to count the number of licks during a task). Below is an example of a setup using two lick spouts in a decision-making task developed by a member of the BRAIN CoGS team.</p><h2 id="two-lick-detection-module-assembly" tabindex="-1">Two lick detection module assembly <a class="header-anchor" href="#two-lick-detection-module-assembly" aria-label="Permalink to “Two lick detection module assembly”">​</a></h2><p>Have the PCB made <a href="https://www.pcbway.com/project/shareproject/Two_spouts_lick_detector_059c7e07.html" target="_blank" rel="noreferrer">here</a> (or download the Gerber files and have it made elsewhere). The step-by-step soldering instructions for the solenoid valve driver in the <a href="/building/control.html#solenoid-valve-driver-assembly">control module</a> also apply to this module; just use the appropriate components and place them as labeled on the PCB.</p><figure><img src="`+a+`" alt="" width="1280" height="932" loading="lazy"></figure><table tabindex="0"><thead><tr><th>Label</th><th>Part No.</th><th>Description</th></tr></thead><tbody><tr><td>R1, R2, R4, R5</td><td><a href="https://www.digikey.com/en/products/detail/yageo/AC1206FR-0710ML/5897214" target="_blank" rel="noreferrer">AC1206FR-0710ML</a></td><td>10 MΩ resistors</td></tr><tr><td>R3, R6</td><td><a href="https://www.digikey.com/en/products/detail/yageo/AC1206FR-0747KL/5897559" target="_blank" rel="noreferrer">AC1206FR-0747KL</a></td><td>47 kΩ resistors</td></tr><tr><td>R7, R8</td><td><a href="https://www.digikey.com/en/products/detail/yageo/ac1206fr-0710kl/5897213" target="_blank" rel="noreferrer">AC1206FR-0710KL</a></td><td>10 kΩ resistors</td></tr><tr><td>T1, T2, T3, T4</td><td><a href="https://www.digikey.com/en/products/detail/onsemi/mmbt2222lt1g/919595" target="_blank" rel="noreferrer">MMBT2222LT1G</a></td><td>NPN BJT transistor</td></tr><tr><td>8L61-12-011 (2)</td><td><a href="https://www.digikey.com/en/products/detail/coto-technology/8l61-12-011/1914969" target="_blank" rel="noreferrer">8L61-12-011</a></td><td>Reed relay, SPDT, 250 mA, 12 V</td></tr><tr><td>U2</td><td><a href="https://www.digikey.com/en/products/detail/texas-instruments/ua78l05acpke6/9860880" target="_blank" rel="noreferrer">UA78L05ACPKE6</a></td><td>Linear voltage regulator</td></tr><tr><td>No label (middle big square)</td><td><a href="https://www.digikey.com/en/products/detail/traco-power/trs-2-2412/9383650" target="_blank" rel="noreferrer">TRS 2-2412</a></td><td>Isolated DC-DC converter module</td></tr><tr><td>C1</td><td><a href="https://www.digikey.com/en/products/detail/samsung-electro-mechanics/cl31b475kbhnnne/3888447" target="_blank" rel="noreferrer">CL31B475KBHNNNE</a></td><td>4.7 µF ceramic capacitor</td></tr><tr><td>C2</td><td><a href="https://www.digikey.com/en/products/detail/samsung-electro-mechanics/cl31c151jbcnnnc/3888469" target="_blank" rel="noreferrer">CL31C151JBCNNNC</a></td><td>150 pF ceramic capacitor</td></tr><tr><td>22 micro</td><td><a href="https://www.digikey.com/en/products/detail/vishay-dale/ifsc1008aber220m01/2744218" target="_blank" rel="noreferrer">IFSC1008ABER220M01</a></td><td>22 µH shielded inductor</td></tr></tbody></table><p>After assembling the module, apply the labels as shown in the picture below.</p><figure><img src="`+i+`" alt="" width="1280" height="932" loading="lazy"></figure><p>The table below describes each pin of the lick detector module.</p><table tabindex="0"><thead><tr><th>PIN</th><th>Description</th></tr></thead><tbody><tr><td>1. GROUND</td><td>Input - ground</td></tr><tr><td>2. 24V</td><td>Input - 24V DC</td></tr><tr><td>3. OUT LEFT</td><td>Output - TTL output pin for the left spout</td></tr><tr><td>4. OUT RIGHT</td><td>Output - TTL output pin for the right spout</td></tr><tr><td>5. RIGHT SPOUT</td><td>Input - Connect the right spout to this pin</td></tr><tr><td>6. LEFT SPOUT</td><td>Input - Connect the left spout to this pin</td></tr><tr><td>7. HEADPLATE</td><td>Input - Connect the head plate to this pin</td></tr><tr><td>8. COMMON</td><td>Input - Connect the ground from the NI-DAQ (or any other acquisition device) to this pin</td></tr></tbody></table><h3 id="soldering-a-cable-to-the-feeding-spout-and-headplate-holder" tabindex="-1">Soldering a cable to the feeding spout and head plate holder <a class="header-anchor" href="#soldering-a-cable-to-the-feeding-spout-and-headplate-holder" aria-label="Permalink to “Soldering a cable to the feeding spout and head plate holder”">​</a></h3><ol><li><p>Sand off the outer layer of the stainless steel spout on one side, near the Luer lock connector (as far as possible from the connector tip). Do the same on the head plate holder wherever you want to attach the cable (we recommend the arm without the tapped hole, so heat-shrink tubing fits over it).</p></li><li><p>Clean the sanded surface with isopropyl alcohol and let it dry. In the meantime, prepare the coaxial cable (we recommend a <a href="https://www.digikey.com/en/products/detail/molex-temp-flex/1000660054/4368709" target="_blank" rel="noreferrer">26</a> or <a href="https://www.digikey.com/en/products/detail/molex/1001935047/8566104" target="_blank" rel="noreferrer">28</a> AWG coaxial cable like these) by removing the jacket and the shield, then strip a portion of the insulation to expose the conductor. Repeat on the other end of the cable.</p></li><li><p>Put a small drop of flux on the sanded surface and place the tip of the soldering iron on it (the tip might stick to the stainless steel; that&#39;s normal). Keep heating the surface and use solder wire (we found leaded solder works best) to solder the coaxial cable to the spout and the head plate holder.</p></li><li><p>Cover the solder joint with heat-shrink tubing.</p></li></ol><p>To close the detection circuit, you need a contact on the mouse&#39;s body. We solder a lead to the head plate holder (repeating steps 1-4), but this can be adapted to other setups.</p>`,14)]])}var l=n(s,[[`render`,c]]);export{o as __pageData,l as default};